
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gvt4_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gvt4", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.600446271019394e+00, -4.508529648613566e+00, -4.379792581856507e+00, -4.201595099543113e+00, -3.959092673127957e+00, -3.637104529128594e+00, -3.224639797229230e+00, -2.723595154816156e+00, -2.161912437617659e+00, -1.593570803735905e+00, -9.729421700669576e-01, -5.700107647466610e-01, -6.350460594909509e-01, -5.194949044856203e-01, -3.706885746170271e-01, -2.399870255900649e-01, -1.246018210944923e-01, -1.485748566838647e-02, -1.874259370963646e-04, -2.794793329726705e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


